`makeNodes(config, waveIndex)`:
 const count=config.nodes,
 step=TAU/count,
 arr=[];
 for (let i=0;i<count;i++){
   const jitter = (Math.sin((i+1)*(waveIndex+1)*2.17)*0.5)*0.10; // [-0.05,0.05]
   const angle = 0.62 + i*step + jitter;
   const rf = 0.205 + ((i*3+waveIndex)%4)*0.045 + ((i%3)*0.008);
   const kind = config.voids.includes(i)?'void':'sync';
   const echo = config.echo.includes(i);
   arr.push({angle, rf, kind, echo, seed:i*2+waveIndex, nextTarget:angle, rev:Math.floor(angle/TAU), flash:0, tapPulse:0, charge:0, lastHit:0});
 }
 return arr;
}
