 if (state.overdriveTime>0){ state.overdriveTime=Math.max(0,state.overdriveTime-dt); if state.overdriveTime===0 { showBanner('SYNC RESTORED','THE PULSE RETURNS TO TEMPO',1200); } }
 const ts = state.overdriveTime>0?0.55:1;
 const spin = state.config.spin*ts*dt;
 if (spin){ for nodes: n.angle += spin; n.nextTarget += spin; }
 state.sweep += state.speed*ts*dt;
