const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const PORT = 9333;
const URL = 'file:///home/runner/work/PlayGround/PlayGround/projects/pulse-lattice/index.html?autostart=1';
const OUT = '/tmp/plshots';

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function main () {
  fs.rmSync('/tmp/plprof', { recursive: true, force: true });
  const chrome = spawn('/usr/bin/chromium', [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars',
    '--disable-background-timer-throttling', '--disable-renderer-backgrounding',
    '--force-device-scale-factor=1', '--window-size=1440,900',
    '--user-data-dir=/tmp/plprof', `--remote-debugging-port=${PORT}`, URL
  ], { stdio: 'ignore' });

  let list = null;
  for (let i = 0; i < 80; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      list = await r.json();
      if (list.length) break;
    } catch (e) {}
    await sleep(150);
  }
  if (!list) { console.error('no devtools'); chrome.kill(); process.exit(1); }
  const target = list.find(t => t.type === 'page');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

  let id = 0;
  const pending = new Map();
  const events = [];
  ws.onmessage = ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    } else if (msg.method) {
      if (msg.method === 'Runtime.exceptionThrown' || msg.method === 'Log.entryAdded' || msg.method === 'Runtime.consoleAPICalled') {
        events.push(msg);
      }
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const mid = ++id;
    pending.set(mid, { resolve, reject });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
  const evaluate = async (expression) => {
    const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
    return r.result.value;
  };
  const shot = async (name) => {
    const r = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(OUT, name), Buffer.from(r.data, 'base64'));
  };

  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');
  await sleep(3800);

  const snap = async (label) => {
    const v = await evaluate(`(() => {
      const s = window.PULSE_LATTICE.state;
      return { mode:s.mode, wave:s.wave, score:s.score, coh:+s.coherence.toFixed(1),
        combo:s.combo, mult:s.mult, od:+s.overdrive.toFixed(1), hits:s.hits, misses:s.misses,
        dodged:s.voidsDodged, voidHits:s.voidHits, sweep:+s.sweep.toFixed(2),
        targets: window.PULSE_LATTICE.nodes().map(n => +n.nextTarget.toFixed(2)) };
    })()`);
    console.log(label, JSON.stringify(v));
    return v;
  };

  await snap('after-load');
  await shot('play-live.png');

  // Auto-player: tap each active sync node when the arm is within its window.
  await evaluate(`(() => {
    if (window.__auto) clearInterval(window.__auto);
    window.__auto = setInterval(() => {
      const g = window.PULSE_LATTICE;
      const s = g.state;
      if (s.mode !== 'playing' || s.leadIn > 0) return;
      g.nodes().forEach((n, i) => {
        const diff = s.sweep - n.nextTarget;
        if (n.kind === 'sync' && Math.abs(diff) < 0.12) g.tap(i);
      });
    }, 9);
  })()`);

  await sleep(4500);
  await snap('auto-4.5s');
  await shot('play-auto.png');

  await sleep(6000);
  await snap('auto-10.5s');
  await shot('play-auto2.png');

  // force overdrive
  await evaluate(`window.PULSE_LATTICE.overdrive()`);
  await sleep(1600);
  await snap('overdrive');
  await shot('play-overdrive.png');

  await sleep(8000);
  await snap('auto-20s');
  await shot('play-auto3.png');

  // pause
  await evaluate(`document.getElementById('pauseBtn').click()`);
  await sleep(600);
  await snap('paused');
  await shot('paused.png');
  await evaluate(`document.getElementById('pauseBtn').click()`);

  const errs = events.filter(e => e.method === 'Runtime.exceptionThrown' || (e.method === 'Log.entryAdded' && e.params.entry.level === 'error'));
  console.log('ERRORS', JSON.stringify(errs.map(e => e.params), null, 1));

  ws.close();
  chrome.kill();
}
main().catch(e => { console.error(e); process.exit(1); });

