    // Render cash flow summary
    function renderCashFlowSummary(transactions) {
      let revenue = 0, expenditure = 0;
      const byAsset = {};

      transactions.forEach(tx => {
        const amount = parseFloat(tx.amount);
        if (tx.type === "revenue") {
          revenue += amount;
          byAsset[tx.asset] = (byAsset[tx.asset] || 0) + amount;
        } else if (tx.type === "expenditure") {
          expenditure += amount;
          byAsset[tx.asset] = (byAsset[tx.asset] || 0) - amount;
        }
      });

      document.getElementById("cf-revenue").textContent = revenue.toFixed(2);
      document.getElementById("cf-expenditure").textContent = expenditure.toFixed(2);
      document.getElementById("cf-net").textContent = (revenue - expenditure).toFixed(2);

      // Render by asset
      const assetEl = document.getElementById("cf-by-asset");
      assetEl.innerHTML = "";
      Object.entries(byAsset).forEach(([asset, amount]) => {
        const sign = amount >= 0 ? "+" : "";
        const el = document.createElement("div");
        el.className = "run";
        el.innerHTML = `<span>${asset}: ${sign}${amount.toFixed(2)}</span>`;
        assetEl.appendChild(el);
      });
