      campaigns.forEach(camp => {
        const ctr = camp.impressions > 0 ? ((camp.clicks / camp.impressions) * 100).toFixed(2) : "0.00";
        const el = document.createElement("div");
        el.className = "run";
        el.innerHTML = `
