          <div>Spend: $${parseFloat(camp.spend || 0).toFixed(2)} | Rev: $${parseFloat(camp.revenue || 0).toFixed(2)}</div>
          <div>CTR: ${ctr}% | Clicks: ${camp.clicks} | Impr: ${camp.impressions}</div>
        `;
