input.newString:
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1500);
  const btn = overlay.querySelector('[data-action="sigil"]');
  if (btn) {
    btn.textContent = 'Memory sigil saved ✓';
    window.setTimeout(() => {
      if (btn.isConnected) btn.textContent = 'Save memory sigil (SVG)';
    }, 1900);
  }
}

input.oldString:
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1500);
  addFloat(view.w / 2, view.h * 0.32, 'SIGIL SAVED', '', '#5ff2df', 0.9);
}

